// IA FALSA, so para o teste local da revisao (15/11/2026). Nao contacta ninguem.
// Geracao: devolve textos reais dos testes com a IA (1.a ronda em proposta-reels/teste-real; 3.a ronda em
// proposta-revisao/teste-real), com as falhas que tinham. Revisoes: correcoes mecanicas, para se ver que
// cada troca entra no sitio certo.
const fs = require('fs');
const path = require('path');
const saida = path.join(__dirname, '..', '..', '..', '..', 'saida');
const raiz = path.join(__dirname, '..', '..', '..', '..', '..', '..');
const real = require(path.join(raiz, 'proposta-reels-2026-11-15', 'teste-real', 'resultado.json'));
const ronda3 = require(path.join(raiz, 'proposta-revisao-2026-11-15', 'teste-real', 'resultado-ronda3.json'));
const ronda4 = require(path.join(raiz, 'proposta-revisao-2026-11-15', 'teste-real', 'resultado-ronda4.json'));
const ronda5 = require(path.join(raiz, 'proposta-revisao-2026-11-15', 'teste-real', 'resultado-ronda5.json'));
const ronda7 = require(path.join(raiz, 'proposta-revisao-2026-11-15', 'teste-real', 'resultado-ronda7.json'));
let n = 0;
const corrigir = (f) => f.replace(/[Tt]alvez /g, '').replace(/algo errado/g, 'um erro').replace(/és obrigada a/g, 'tens de')
  .replace(/Em sessão, ouço isto quase todas as semanas/g, 'Em sessão, ouço esta frase')
  .replace(/decepcionar/g, 'dececionar')
  .replace(/seres desiludido/g, 'te desiludirem').replace(/estás sozinho/g, 'só podes contar contigo')
  .replace(/seres apanhada de surpresa/g, 'te apanharem de surpresa').replace(/chama se/g, 'chama-se')
  .replace(/A confiança constrói-se na raiz\./g, 'A confiança nasce na raiz.');
const corta = (t, max) => t.split(/\s+/).slice(0, max).join(' ').replace(/[,;:]?$/, '.');
class Anthropic {
  constructor() {
    this.messages = {
      create: async (params) => {
        n += 1;
        const ferramenta = params.tools[0].name;
        const pedido = params.messages[0].content;
        fs.writeFileSync(path.join(saida, `${String(n).padStart(2, '0')}-${process.env.CENARIO || 'teste'}-${ferramenta}.txt`),
          `=== SYSTEM ===\n${params.system}\n\n=== PEDIDO ===\n${pedido}\n`);
        let input;
        const c = process.env.CENARIO || '';
        if (ferramenta === 'devolver_textos') input = { textos: JSON.parse(pedido) };
        else if (ferramenta === 'devolver_frases') input = { frases: JSON.parse(pedido).map(x => corrigir(x.frase)) };
        else if (ferramenta === 'devolver_genero') input = { trocas: JSON.parse(pedido).filter(x => /mais sozinho|continuar parado/.test(x.frase))
          .map(x => ({ n: x.n, nova: x.frase.replace('mais sozinho', 'mais sem apoio').replace('continuar parado', 'continuar em pausa') })) };
        else if (ferramenta === 'devolver_falas') {
          const d = JSON.parse(pedido); const bl = d.blocos || d;
          // No cenario "teimosa", a IA ignora os maximos e devolve as falas iguais (como aconteceu na setima ronda)
          input = { falas: bl.map(x => (c.includes('teimosa') ? x.fala : corta(x.fala, x.max_palavras))) };
        }
        else if (ferramenta === 'devolver_textos_peca') input = { textos: JSON.parse(pedido).reescrever.map(x => (/outro CTA/.test(x.problema)
          ? 'Que frase dizes a ti quando alguém não responde?'
          : /repete uma frase/.test(x.problema) ? 'Por trás dessa leitura costuma estar uma regra antiga sobre o teu valor.'
          : 'Há quem passe anos a provar o seu valor sem perceber de onde vem essa exigência.')) };
        else if (ferramenta === 'entregar_ganchos') input = /Receita R3/.test(params.system) ? real.aberturasR3 : real.aberturas;
        else if (ferramenta === 'entregar_roteiro') input = c.startsWith('ronda7-r3') ? ronda7.r3.roteiro : c.startsWith('ronda5-r3') ? ronda5.r3.roteiro : c.startsWith('ronda4-r3') ? ronda4.r3.roteiro : c.startsWith('ronda4-sig') ? ronda4.significado.roteiro
          : c.startsWith('ronda3-r3') ? ronda3.r3.roteiro : (/sessao/.test(pedido) ? real.roteiroR3 : real.roteiro);
        else if (ferramenta === 'entregar_carrossel') input = c.startsWith('ronda4') ? ronda4.carrossel.carrossel : ronda3.carrossel.carrossel;
        else throw new Error('IA falsa: ferramenta sem resposta ' + ferramenta);
        return { content: [{ type: 'tool_use', name: ferramenta, input: JSON.parse(JSON.stringify(input)) }] };
      },
    };
  }
}
module.exports = Anthropic;
module.exports.default = Anthropic;
